  }
  if (Length() == 0.0)
  {
    return false;
  }
  BND_Point3dX A = m_from;
  BND_Point3dX B = m_to;
  BND_Vector3dX tan = UnitTangent();
  if (startLength != 0.0)
  {
    A = m_from - startLength * tan;
  }
  if (endLength != 0.0)
  {
    B = m_to + endLength * tan;
  }
  m_from = A;
  m_to = B;
  return true;
}

