std::vector<BND_LineX> BND_BoundingBoxX::GetEdges() const
{
  if (!IsValid())
  {
    return std::vector<BND_LineX>();
  }
  std::vector<BND_LineX> edges = std::vector<BND_LineX>(12);
  BND_Point3dX minPt = Min();
  BND_Point3dX maxPt = Max();
  (edges[0]).set_From(minPt);
  (edges[0]).set_To(BND_Point3dX((maxPt).X(), (minPt).Y(), (minPt).Z()));
  (edges[1]).set_From((edges[0]).To());
  (edges[1]).set_To(BND_Point3dX((maxPt).X(), (maxPt).Y(), (minPt).Z()));
  (edges[2]).set_From((edges[1]).To());
  (edges[2]).set_To(BND_Point3dX((minPt).X(), (maxPt).Y(), (minPt).Z()));
  (edges[3]).set_From((edges[2]).To());
  (edges[3]).set_To(minPt);
  for (int i = 0; i < 4; i++)
  {
    edges[i + 4] = edges[i];
