bool BND_PlaneX::ExtendThroughPoints(const std::vector<BND_Point3dX>& pts, BND_IntervalX& s, BND_IntervalX& t) const
{
  double s0 = std::numeric_limits<double>::max();
  double s1 = std::numeric_limits<double>::lowest();
  double t0 = std::numeric_limits<double>::max();
  double t1 = std::numeric_limits<double>::lowest();
  bool valid = false;
  for (BND_Point3dX pt : pts)
  {
    double sp;
    double tp;
    if (ClosestParameter(pt, sp, tp))
    {
      valid = true;
      s0 = RH3DM_Min(s0, sp);
      s1 = RH3DM_Max(s1, sp);
      t0 = RH3DM_Min(t0, tp);
      t1 = RH3DM_Max(t1, tp);
    }
  }
  if (valid)
  {
    s = BND_IntervalX(s0, s1);
    t = BND_IntervalX(t0, t1);
  }
  return valid;
}

bool BND_PlaneX::ClosestParameter(BND_Point3dX testPoint, double& s, double& t) const
{
  BND_Vector3dX v = testPoint - Origin();
  s = v * XAxis();
  t = v * YAxis();
  return true;
}

BND_Point3dX BND_PlaneX::ClosestPoint(BND_Point3dX testPoint) const
{
  double s;
  double t;
  return (!ClosestParameter(testPoint, s, t) ? BND_Point3dX::Unset() : PointAt(s, t));
}

