double BND_TransformX::get_Item(int row, int column) const
{
  if (row < 0)
  {
    throw std::out_of_range("Negative row indices are not allowed when accessing a Transform matrix");
  }
  if (row > 3)
  {
    throw std::out_of_range("Row indices higher than 3 are not allowed when accessing a Transform matrix");
  }
  if (column < 0)
  {
    throw std::out_of_range("Negative column indices are not allowed when accessing a Transform matrix");
  }
  if (column > 3)
  {
    throw std::out_of_range("Column indices higher than 3 are not allowed when accessing a Transform matrix");
  }
  if (row == 0)
  {
    if (column == 0)
    {
      return m_00;
    }
    if (column == 1)
    {
      return m_01;
    }
    if (column == 2)
    {
      return m_02;
    }
    if (column == 3)
    {
      return m_03;
    }
  }
  else
  {
    if (row == 1)
    {
      if (column == 0)
      {
        return m_10;
      }
      if (column == 1)
      {
        return m_11;
      }
      if (column == 2)
      {
        return m_12;
      }
      if (column == 3)
      {
        return m_13;
      }
    }
    else
    {
      if (row == 2)
      {
        if (column == 0)
        {
          return m_20;
        }
        if (column == 1)
        {
          return m_21;
        }
        if (column == 2)
        {
          return m_22;
        }
        if (column == 3)
        {
          return m_23;
        }
      }
      else
      {
        if (row == 3)
        {
          if (column == 0)
          {
            return m_30;
          }
          if (column == 1)
          {
            return m_31;
          }
          if (column == 2)
          {
            return m_32;
          }
          if (column == 3)
          {
            return m_33;
          }
        }
      }
    }
  }
  throw std::out_of_range("One of the cross beams has gone out askew on the treadle.");
}

