{
  m_plane = basePlane;
  m_dx = BND_IntervalX(((boundingbox).Min()).X(), ((boundingbox).Max()).X());
  m_dy = BND_IntervalX(((boundingbox).Min()).Y(), ((boundingbox).Max()).Y());
  m_dz = BND_IntervalX(((boundingbox).Min()).Z(), ((boundingbox).Max()).Z());
