BND_RhinoListPoint3dX::BND_RhinoListPoint3dX(int amount, BND_Point3dX defaultValue)
{
  if (amount < 0)
  {
    throw std::out_of_range("RhinoList cannot be constructed with a negative amount (Parameter 'amount')");
  }
  if (amount == 0)
  {
    return;
  }
  m_items = std::vector<BND_Point3dX>(amount);
  m_size = amount;
  for (int i = 0; i < amount; i++)
  {
    m_items[i] = defaultValue;
  }
}

BND_RhinoListPoint3dX::BND_RhinoListPoint3dX(const std::vector<BND_Point3dX>& collection)
{
  std::vector<BND_Point3dX> is2 = collection;
  {
    int count = ((int)is2.size());
    m_items = std::vector<BND_Point3dX>(count);
    RH3DM_ArrCopy(is2, 0, m_items, 0, (int)is2.size());
    m_size = count;
  }
}

std::vector<BND_Point3dX> BND_RhinoListPoint3dX::ToArray() const
{
  std::vector<BND_Point3dX> destinationArray = std::vector<BND_Point3dX>(m_size);
  RH3DM_ArrCopy(m_items, 0, destinationArray, 0, m_size);
  return destinationArray;
}

void BND_RhinoListPoint3dX::EnsureCapacity(int min)
{
  if (((int)m_items.size()) < min)
  {
    int num = ((((int)m_items.size()) == 0) ? 4 : (((int)m_items.size()) * 2));
    if (num < min)
    {
      num = min;
    }
    set_Capacity(num);
  }
}

