void BND_RhinoListPoint3dX::set_Capacity(int value)
{
  if (value != ((int)m_items.size()))
  {
    if (value < m_size)
    {
      throw std::out_of_range("Capacity must be larger than or equal to the list Count (Parameter 'value')");
    }
    if (value > 0)
    {
      std::vector<BND_Point3dX> destinationArray = std::vector<BND_Point3dX>(value);
      if (m_size > 0)
      {
        RH3DM_ArrCopy(m_items, 0, destinationArray, 0, m_size);
