void BND_RhinoListPoint3dX::Add(BND_Point3dX item)
{
  if (m_size == ((int)m_items.size()))
  {
    EnsureCapacity(m_size + 1);
  }
  m_items[m_size++] = item;
  m_version++;
}

void BND_RhinoListPoint3dX::AddRange(const std::vector<BND_Point3dX>& collection)
{
  InsertRange(m_size, collection);
}

void BND_RhinoListPoint3dX::Insert(int index, BND_Point3dX item)
{
  if (index > m_size)
  {
    throw std::out_of_range("Specified argument was out of the range of valid values. (Parameter 'index')");
  }
  if (m_size == ((int)m_items.size()))
  {
    EnsureCapacity(m_size + 1);
  }
  if (index < m_size)
  {
    RH3DM_ArrCopy(m_items, index, m_items, index + 1, m_size - index);
  }
  m_items[index] = item;
  m_size++;
  m_version++;
}

void BND_RhinoListPoint3dX::InsertRange(int index, const std::vector<BND_Point3dX>& collection)
{
  if (index > m_size)
  {
    throw std::out_of_range("Specified argument was out of the range of valid values. (Parameter 'index')");
  }
  std::vector<BND_Point3dX> is2 = collection;
  {
    int count = ((int)is2.size());
    if (count > 0)
    {
      EnsureCapacity(m_size + count);
      if (index < m_size)
      {
        RH3DM_ArrCopy(m_items, index, m_items, index + count, m_size - index);
      }
      {
        std::vector<BND_Point3dX> array = std::vector<BND_Point3dX>(count);
        RH3DM_ArrCopy(is2, 0, array, 0, (int)is2.size());
        RH3DM_ArrCopy(array, 0, m_items, index, (int)array.size());
      }
      m_size += count;
    }
  }
  m_version++;
}

bool BND_RhinoListPoint3dX::Remove(BND_Point3dX item)
{
  int index = IndexOf(item);
  if (index >= 0)
  {
    RemoveAt(index);
    return true;
  }
