void BND_PolylineX::Collapse_CollapseSegment(int segment_index, std::vector<double>& L, std::vector<BND_Point3dX>& P)
{
  if (segment_index == 0)
  {
    P.erase(P.begin() + (1));
    L.erase(L.begin() + (0));
    L[0] = (P[0]).DistanceTo(P[1]);
