int BND_PolylineX::ReduceSegments(double tolerance)
{
  if (m_size < 3)
  {
    return 0;
  }
  if (m_size < 5 && IsClosed())
  {
    return 0;
  }
  std::vector<bool> vertexMap = std::vector<bool>(m_size);
  vertexMap[0] = true;
  vertexMap[m_size - 1] = true;
  Reduce_RecursiveComponent(m_items, vertexMap, tolerance, 0, m_size - 1);
  int n = 0;
  for (int i = 0; i < ((int)vertexMap.size()); i++)
  {
    if (vertexMap[i])
    {
      m_items[n] = m_items[i];
      n++;
    }
  }
  if (n < 2)
  {
    Clear();
    return ((int)vertexMap.size());
  }
  m_size = n;
  return ((int)vertexMap.size()) - m_size;
}

void BND_PolylineX::Reduce_RecursiveComponent(const std::vector<BND_Point3dX>& p, std::vector<bool>& vertexMap, double tolerance, int a, int b)
{
  if (b <= (a + 1))
  {
    return;
  }
  BND_LineX segment = BND_LineX(p[a], p[b]);
  double maxDeviation = 0.0;
  int maxIndex = a;
  for (int i = a + 1; i < b; i++)
  {
    double localDeviation = (segment).MinimumDistanceTo(p[i]);
    if (localDeviation > maxDeviation)
    {
      maxDeviation = localDeviation;
      maxIndex = i;
    }
  }
  if (maxDeviation > tolerance)
  {
    vertexMap[maxIndex] = true;
    Reduce_RecursiveComponent(p, vertexMap, tolerance, a, maxIndex);
    Reduce_RecursiveComponent(p, vertexMap, tolerance, maxIndex, b);
  }
}

bool BND_PolylineX::Smooth(double amount)
{
  int count = Count();
  if (count < 3)
  {
    return false;
  }
  int N = count - 1;
  amount *= 0.5;
  std::vector<BND_Point3dX> v = std::vector<BND_Point3dX>(count);
  if (IsClosed())
  {
    v[0] = Smooth(m_items[N - 1], m_items[0], m_items[1], amount);
    v[N] = v[0];
  }
  else
  {
    v[0] = m_items[0];
    v[N] = m_items[N];
  }
  for (int i = 1; i < N; i++)
  {
    v[i] = Smooth(m_items[i - 1], m_items[i], m_items[i + 1], amount);
  }
  m_items = v;
  return true;
}

BND_Point3dX BND_PolylineX::Smooth(BND_Point3dX v0, BND_Point3dX v1, BND_Point3dX v2, double amount)
{
  double x = 0.5 * ((v0).m_x + (v2).m_x);
  double y = 0.5 * ((v0).m_y + (v2).m_y);
  double z = 0.5 * ((v0).m_z + (v2).m_z);
  double bx = ((x == (v1).m_x) ? x : (v1).m_x + amount * (x - (v1).m_x));
  double by = ((y == (v1).m_y) ? y : (v1).m_y + amount * (y - (v1).m_y));
  double bz = ((z == (v1).m_z) ? z : (v1).m_z + amount * (z - (v1).m_z));
  return BND_Point3dX(bx, by, bz);
}

BND_Point3dX BND_PolylineX::CenterPoint() const
{
  if (Count() == 0)
  {
    return BND_Point3dX::Unset();
  }
  if (Count() == 1)
  {
    return get_Item(0);
  }
  BND_Point3dX center = BND_Point3dX::Origin();
  double weight = 0.0;
  for (int i = 0; i < (Count() - 1); i++)
  {
    BND_Point3dX A = get_Item(i);
    BND_Point3dX B = get_Item(i + 1);
    double d = (A).DistanceTo(B);
    center = center + (d * 0.5 * (A + B));
    weight += d;
  }
  center = center / (weight);
  return center;
}

